CAMPOS_IPVA = ("ipva_ano", "ipva_valor", "ipva_vencimento", "ipva_pago_em")


def _registro(obj, ano_reserva):
    """Dados de IPVA de um Veiculo (ou de uma versão do histórico), ou None se vazio."""
    if all(getattr(obj, campo) is None for campo in CAMPOS_IPVA):
        return None
    data = obj.ipva_vencimento or obj.ipva_pago_em
    ano = obj.ipva_ano or (data.year if data else ano_reserva)
    return {
        "ano": ano,
        "valor": obj.ipva_valor,
        "vencimento": obj.ipva_vencimento,
        "pago_em": obj.ipva_pago_em,
    }


def _guardar(por_ano, registro):
    """Grava o registro do ano; o mesmo pagamento (data e valor) só fica num ano.

    Ano digitado errado e corrigido depois deixa no histórico uma versão com o
    ano errado e o mesmo pagamento — sem isto o IPVA entraria duas vezes na despesa.
    """
    if registro["pago_em"] is not None:
        for ano, outro in list(por_ano.items()):
            if (
                ano != registro["ano"]
                and outro["pago_em"] == registro["pago_em"]
                and outro["valor"] == registro["valor"]
            ):
                del por_ano[ano]
    por_ano[registro["ano"]] = registro


def copiar_ipva(apps, schema_editor):
    """Copia o IPVA de cada carro para PagamentoIpva — sem perder dado nenhum.

    Além do IPVA atual, recupera do histórico (simple-history) os anos que já
    tinham sido sobrescritos: para cada ano fica a última versão gravada.
    """
    Veiculo = apps.get_model("frota", "Veiculo")
    HistoricalVeiculo = apps.get_model("frota", "HistoricalVeiculo")
    PagamentoIpva = apps.get_model("frota", "PagamentoIpva")
    hoje = date.today()
    for veiculo in Veiculo.objects.all():
        por_ano = {}
        versoes = HistoricalVeiculo.objects.filter(id=veiculo.pk).order_by(
            "history_date", "history_id"
        )
        for versao in versoes:
            registro = _registro(versao, versao.history_date.year)
            if registro:
                _guardar(por_ano, registro)
        atual = _registro(veiculo, hoje.year)
        if atual:
            _guardar(por_ano, atual)  # o cadastro de hoje vale sobre o histórico
        for registro in por_ano.values():
            PagamentoIpva.objects.create(veiculo=veiculo, parcela=1, **registro)


def devolver_ipva(apps, schema_editor):
    """Volta: o ano mais recente (1ª parcela) de cada carro retorna aos campos do Veiculo."""
    Veiculo = apps.get_model("frota", "Veiculo")
    PagamentoIpva = apps.get_model("frota", "PagamentoIpva")
    for veiculo in Veiculo.objects.all():
        ultimo = PagamentoIpva.objects.filter(veiculo=veiculo).order_by("-ano", "parcela").first()
        if ultimo:
            veiculo.ipva_ano = ultimo.ano
            veiculo.ipva_valor = ultimo.valor
            veiculo.ipva_vencimento = ultimo.vencimento
            veiculo.ipva_pago_em = ultimo.pago_em
            veiculo.save(update_fields=list(CAMPOS_IPVA))


